import { Component } from './Component';
import { ensureElement } from '../utils/utils';
export class SuccessModal extends Component {
    constructor(container, events) {
        super(container);
        this._description = ensureElement(`.order-success__description`, this.container);
        this._closeButton = ensureElement(`.order-success__close`, this.container);
        this._closeButton.addEventListener('click', () => {
            events.emit('SuccessOrder');
        });
    }
    set description(value) {
        this.setText(this._description, `Списано ${value} синапсов`);
    }
}
