import { Component } from './Component';
import { createElement, ensureElement } from './../utils/utils';
export class Basket extends Component {
    constructor(container, events) {
        super(container);
        this.events = events;
        this._list = ensureElement('.basket__list', this.container);
        this._price = ensureElement('.basket__price', this.container);
        this._button = ensureElement('.basket__button', this.container);
        if (this._button) {
            this._button.addEventListener('click', () => {
                events.emit('OrderStart');
            });
        }
        this.items = [];
        this.setEmpty();
    }
    updateBasket() {
        const items = Array.from(this._list.children);
        const isBasketEmpty = items.length === 0;
        if (!isBasketEmpty) {
            items.forEach((item, index) => {
                const itemIndex = item.querySelector('.basket__item-index');
                itemIndex && (itemIndex.textContent = String(index + 1));
            });
            this._button.removeAttribute('disabled');
        }
        else {
            this.setEmpty();
        }
    }
    setEmpty() {
        const emptyParagraph = createElement('p', { textContent: 'Корзина пуста' });
        this._list.replaceChildren(emptyParagraph);
        this._button.setAttribute('disabled', 'true');
    }
    set items(items) {
        if (items.length) {
            items.forEach((item, index) => {
                const itemIndex = item.querySelector('.basket__item-index');
                if (itemIndex) {
                    itemIndex.textContent = String(index + 1);
                }
            });
            this._list.replaceChildren(...items);
        }
    }
    set total(value) {
        this.setText(this._price, `${value} синапсов`);
    }
    get list() {
        return this._list;
    }
}
